// Each built scene's IR, world, compositor and scene.bin buffers, which load gives its controls.
const IRS = new WeakMap(), WORLDS = new WeakMap(), COMPOSITORS = new WeakMap(), SCENE_BUFFERS = new WeakMap();
export const createEngine = async (canvas, options = {}) => new Engine(canvas, true, options);
// The scene with its controller: load(engine) builds it in a scene of its own, as the page does, with the scene's
// settings; load({ scene, root }) adds its objects to a scene of yours, as a .glb's are, under
// a root of their own, "__root__" (bylonder/asset.js), itself under `root` (a node of yours) if given, with none of the
// scene's settings; load({ instance, root }) copies what a load added, sharing its geometry, materials and textures. A
// load resolves once the scene's shaders are compiled.
export async function load(target) {
  if (target.scene || target.instance) {
    const { ir, buffers } = target.instance ?? await readData(), options = { root: target.root,
      controller: (view, entries, dispose) => new BlendScene(view, ir, { root: ROOT, buffers, entries, dispose }) };
    if (target.instance) return cloneAsset(target.instance.entries, options);
    const added = addAsset(target.scene, (into, lookup) => addObjects(into, { ir, buffers }, lookup), options);
    await shadersCompiled(target.scene);
    return added;
  }
  const engine = target;
  const scene = await createScene(engine, engine.getRenderingCanvas());
  await shadersCompiled(scene);
  return new BlendScene(scene, IRS.get(scene), { root: ROOT, world: WORLDS.get(scene), compositor: COMPOSITORS.get(scene), buffers: SCENE_BUFFERS.get(scene) });
}

// Once the scene's shaders are compiled, so that a page's first frames do not stall on them: a frame drawn (its time
// held) sets what each material compiles for. At once without a canvas (Node's Null engine compiles nothing).
async function shadersCompiled(scene) {
  if (!scene.getEngine().getRenderingCanvas() || !scene.activeCamera) return;
  scene.render(true, true);
  await scene.whenReadyAsync(true);
}

// The objects in an AssetContainer, as LoadAssetContainerAsync gives a .glb's: instantiate() loads a copy with its own controller.
export async function loadAssetContainer(scene) {
  const blend = await load({ scene });
  return assetContainer(blend, (root) => load({ instance: blend, root }));
}

// scene.bin's buffers and the IR.
async function readData() {
  const buffers = await readBuffers(new URL('scene.bin', ROOT), BUFFERS, true);
  // The IR as data: read as bytes, as Node's fetch reads no file: URL.
  const ir = JSON.parse(new TextDecoder().decode(await readBytes(new URL('scene.ir.json', ROOT))));
  return { buffers, ir };
}

export async function createScene(engine, canvas) {
  const scene = new Scene(engine);
  scene.useRightHandedSystem = SCENE.useRightHandedSystem;
  scene.autoClear = SCENE.autoClear;
  scene.clearColor = Color4.FromArray(SCENE.clearColor);
  scene.ambientColor = Color3.FromArray(SCENE.ambientColor);
  scene.gravity = Vector3.FromArray(SCENE.gravity);
  scene.collisionsEnabled = SCENE.collisionsEnabled;
  if (SCENE.fog) Object.assign(scene, SCENE.fog, { fogColor: Color3.FromArray(SCENE.fog.fogColor) });
  SerializationHelper.Parse(() => scene.imageProcessingConfiguration, IMAGE_PROCESSING, scene);
  scene.environmentIntensity = SCENE.environmentIntensity;
  scene.iblIntensity = SCENE.iblIntensity ?? 1;
  const data = await readData(), { buffers } = data;
  SCENE_BUFFERS.set(scene, buffers);
  IRS.set(scene, data.ir);
  const materials = addObjects(scene, data);
  if (SCENE.defaultMaterial !== null) scene.defaultMaterial = materials[SCENE.defaultMaterial];
  // The world lights the scene: its color, or its nodes baked once their shader is ready.
  const world = SCENE.world;
  if (world) WORLDS.set(scene, world.material !== null ? worldNodes(scene, materials[world.material]) : worldColor(scene, world.color));
  if (SCENE.environmentProbe) scene.environmentTexture = scene.reflectionProbes.find((p) => p.name === SCENE.environmentProbe)?.cubeTexture ?? scene.environmentTexture;
  scene.activeCamera = scene.getCameraById(null) ?? scene.cameras[0] ?? null;

  if (canvas) scene.activeCamera?.attachControl(canvas, true);
  return scene;
}

// A clip's bone keys from scene.bin: smallest-three rotations, location and scale on 16 bits over their ranges
// (io_scene_babylon/clip-export.js binaryClipKeys), composed into matrices as Babylon's Matrix.Compose does.
function clipKeys(entry, buffers) {
  const R = Math.SQRT1_2, table = entry.bylonderTracks;
  if (table) {
    const rows = buffers[table.rows], size = rows.length / table.targets.length, column = (row, i) => (rows[row * size + i] < 0 ? undefined : rows[row * size + i]);
    entry.targetedAnimations = [...entry.targetedAnimations, ...table.targets.map((targetId, row) => {
      const at = row * size, ranges = Array.from(rows.subarray(at + 6, at + 18)), scaled = rows[at + 5] === 1;
      const keys = { frames: column(row, 0), values: column(row, 1), rotation: column(row, 2), location: column(row, 3), scale: scaled ? column(row, 4) : undefined,
        locationRange: [ranges.slice(0, 3), ranges.slice(3, 6)], scaleRange: scaled ? [ranges.slice(6, 9), ranges.slice(9, 12)] : undefined };
      return { targetId, animation: { name: '', property: table.property, dataType: table.dataType, framePerSecond: table.framePerSecond, loopBehavior: table.loopBehavior, keys: [], bylonderKeys: keys } };
    })];
    delete entry.bylonderTracks;
  }
  for (const { animation } of entry.targetedAnimations) {
    const packed = animation.bylonderKeys;
    if (!packed) continue;
    const frames = buffers[packed.frames];
    if (packed.values !== undefined) {
      const values = buffers[packed.values];
      animation.keys = Array.from(frames, (frame, i) => {
        const m = values.subarray(i * 12, i * 12 + 12);
        return { frame, values: [m[0], m[1], m[2], 0, m[3], m[4], m[5], 0, m[6], m[7], m[8], 0, m[9], m[10], m[11], 1] };
      });
      continue;
    }
    const turns = buffers[packed.rotation], at = buffers[packed.location], sizes = packed.scale === undefined ? null : buffers[packed.scale];
    const unpack = (data, [min, extent], i, k) => min[k] + (data[i * 3 + k] / 65535) * extent[k];
    animation.keys = Array.from(frames, (frame, i) => {
      const q = [0, 0, 0, 0], largest = turns[i * 4 + 3];
      let sum = 0;
      for (let k = 0, j = 0; k < 4; k++) if (k !== largest) { q[k] = (turns[i * 4 + j++] / 65535) * 2 * R - R; sum += q[k] * q[k]; }
      q[largest] = Math.sqrt(Math.max(0, 1 - sum));
      const [x, y, z, w] = q, [sx, sy, sz] = sizes ? [0, 1, 2].map((k) => unpack(sizes, packed.scaleRange, i, k)) : [1, 1, 1];
      const t = [0, 1, 2].map((k) => unpack(at, packed.locationRange, i, k));
      return { frame, values: [(1 - 2 * (y * y + z * z)) * sx, 2 * (x * y + z * w) * sx, 2 * (x * z - y * w) * sx, 0,
        2 * (x * y - z * w) * sy, (1 - 2 * (x * x + z * z)) * sy, 2 * (y * z + x * w) * sy, 0,
        2 * (x * z + y * w) * sz, 2 * (y * z - x * w) * sz, (1 - 2 * (x * x + y * y)) * sz, 0, t[0], t[1], t[2], 1] };
    });
  }
  return entry;
}

// A morph target manager's targets from scene.bin: its basis, and each target's moved vertices' offsets
// (io_scene_babylon/morph-export.js).
function morphKeys(entry, buffers) {
  if (!entry.bylonderBasis) return entry;
  const targets = entry.targets.map(({ bylonderSparse: sparse, ...target }) => {
    const vertices = buffers[sparse.vertices], full = {};
    for (const [kind, index] of Object.entries(entry.bylonderBasis)) {
      const array = Float32Array.from(buffers[index]), offsets = buffers[sparse[kind]];
      vertices.forEach((v, i) => { for (let k = 0; k < 3; k++) array[v * 3 + k] += offsets[i * 3 + k]; });
      full[kind] = array;
    }
    return { ...target, ...full };
  });
  return { ...entry, targets };
}

// The exported objects added to `scene` at once, without awaiting: `lookup` finds by id what this call made
// (bylonder/asset.js). Gives the materials by their exported unique ids.
function addObjects(scene, { buffers, ir }, lookup = scene) {
  const materials = {}, entries = structuredClone(MATERIALS);
  // A custom block's code is written once for every material that shares it.
  for (const entry of entries) for (const block of entry.blocks ?? []) if (typeof block.options?.code === 'number') block.options.code = CODE[block.options.code];
  // Blender's nodes of each material and world, made from the IR's graphs.
  fillMaterials(entries, ir, kernels);
  for (const entry of entries) materials[entry.uniqueId] = Material.Parse(entry, scene, ROOT);
  // Each mesh's own texture space, in the materials it shares.
  for (const material of Object.values(materials)) meshValues(material);
  // Lights' specular as a registered unit gives it, else as EEVEE's, as the app's PBR materials have it.
  const areaSpecular = unitFor('block:area_specular')?.apply ?? blenderAreaSpecular;
  if (areaSpecular) for (const material of Object.values(materials)) if (material.getClassName() === 'PBRMaterial') areaSpecular(material);
  // A multi-material's slots by the exported materials' unique ids, as Babylon's loader resolves them after parsing.
  for (const entry of MULTI_MATERIALS) {
    const multi = materials[entry.uniqueId] = MultiMaterial.ParseMultiMaterial(entry, scene);
    multi.subMaterials = (entry.materialsUniqueIds ?? []).map((id) => materials[id] ?? null);
  }
  for (const entry of SKELETONS) Skeleton.Parse(entry, scene);
  const morphTargets = {};
  for (const entry of MORPH_TARGETS) morphTargets[entry.id] = MorphTargetManager.Parse(morphKeys(entry, buffers), scene);
  const geometries = [
  geometry(scene, { "position": [3, buffers[0]], "normal": [3, buffers[1]], "uv": [2, buffers[2]], "matricesIndices": [4, buffers[3]], "matricesWeights": [4, buffers[4]] }, buffers[5]),
  geometry(scene, { "position": [3, buffers[6]], "normal": [3, buffers[7]], "uv": [2, buffers[8]] }, buffers[9]),
  geometry(scene, { "position": [3, buffers[10]], "normal": [3, buffers[11]] }, buffers[12]),
  geometry(scene, { "position": [3, buffers[13]], "normal": [3, buffers[14]], "uv": [2, buffers[15]] }, buffers[16]),
  ];

  const nodes = {};
  // Tea Break
  {
    const node = new Mesh("Tea Break", scene);
    geometries[0].applyToMesh(node);
    node.id = "Tea Break";
    node.position.set(0, 0, 0);
    node.rotationQuaternion = new Quaternion(0, 0, 0, 1);
    node.scaling.set(1, 1, 1);
    node.receiveShadows = true;
    node.material = materials[811] ?? null;
    node.skeleton = lookup.getSkeletonById("Tea Break Rig");
    node.numBoneInfluencers = 4;
    node.metadata = {"bylonderBounds":[[-1.0511297315218542,-1.7904283948828899,-5.323961784270141],[1.0220977453207238,2.0371730594782576,0.04461348704340784]]};
    nodes[1594] = node;
  }
  // Tea Break Rig
  {
    const node = new Mesh("Tea Break Rig", scene);
    node.id = "Tea Break Rig";
    node.position.set(-0.0318003, 0, -0.1998609);
    node.rotationQuaternion = new Quaternion(0.2418449, -0.6644628, 0.6644631, 0.2418448);
    node.scaling.set(0.3589588, 0.3589588, 0.3589588);
    node.isVisible = false;
    nodes[1595] = node;
  }
  // Tea Cup
  {
    const node = new Mesh("Tea Cup", scene);
    geometries[1].applyToMesh(node);
    node.id = "Tea Cup";
    node.position.set(-0.0780231, 0.1204323, 0.2408573);
    node.rotationQuaternion = new Quaternion(0.7280216, 0.1138602, 0.5151411, 0.4377786);
    node.scaling.set(2.7858358, 2.7858373, 2.7858347);
    node.receiveShadows = true;
    node.material = materials[1232] ?? null;
    nodes[1596] = node;
  }
  // Tea Steam Card
  {
    const node = new Mesh("Tea Steam Card", scene);
    geometries[2].applyToMesh(node);
    node.id = "Tea Steam Card";
    node.position.set(0, 0, 0);
    node.rotationQuaternion = new Quaternion(0, 0, 0, 1);
    node.receiveShadows = true;
    node.material = materials[1175] ?? null;
    nodes[1597] = node;
  }
  // Tea Steam Emitter
  {
    const node = new Mesh("Tea Steam Emitter", scene);
    geometries[3].applyToMesh(node);
    node.id = "Tea Steam Emitter";
    node.position.set(-1e-7, 0.05, -1e-7);
    node.rotationQuaternion = new Quaternion(-7e-7, 0.9441619, -5e-7, 0.329482);
    node.scaling.set(0.9999994, 0.9999999, 1.0000004);
    node.receiveShadows = true;
    nodes[1598] = node;
  }
  // Tea Steam Emitter Instances
  {
    const node = new Mesh("Tea Steam Emitter Instances", scene);
    geometries[2].applyToMesh(node);
    node.id = "Tea Steam Emitter Instances";
    node.position.set(0, 0, 0);
    node.isPickable = false;
    node.alwaysSelectAsActiveMesh = true;
    node.material = materials[1175] ?? null;
    node.thinInstanceSetBuffer('matrix', buffers[17], 16, true);
    nodes[1827] = node;
  }

  nodes[1594].parent = nodes[1595] ?? null;
  nodes[1596].parent = nodes[1595] ?? null;
  nodes[1598].parent = nodes[1596] ?? null;
  nodes[1827].parent = nodes[1598] ?? null;
  // Objects parented to bones, hung from them as the bones' meshes are skinned.
  nodes[1596].attachToBone(lookup.getSkeletonById("Tea Break Rig").bones[17], nodes[1594]);

  // Every material takes as many lights as its shader holds, each mesh the package's lights that reach it, the strongest
  // first (EEVEE has no cap); lights the page adds come first where they light.
  const lights = LIGHTS.map((entry) => nodes[entry.uniqueId]);
  reachLights(scene, lights);
  // Bones' poses interpolated between their keys, as between frames and on a grid sparser than the frames.
  Animation.AllowMatricesInterpolation = true;
  // Started and held: the page's playhead (playhead.js) sets them to its frame; a clip (an action's) waits to be played.
  for (const entry of ANIMATION_GROUPS) {
    const group = AnimationGroup.Parse(clipKeys(entry, buffers), lookup);
    if (!entry.metadata?.bylonder?.clip) group.start(entry.loopAnimation).pause();
  }
  return materials;
}
